43	// ExportSnapshot writes a package containing the target snapshot's complete
44	// mapping and the content objects it references. When baseName is empty every
45	// referenced object is carried; when set, only objects not referenced by the
46	// base snapshot are carried. The package always records the target's full
47	// mapping. Every object referenced by the target — including ones omitted from
48	// an incremental package — is verified for existence, size, and SHA-256 before
49	// the package is written. A failure leaves any existing output file untouched.
50	func (s *Store) ExportSnapshot(name, output, baseName string) (ExportResult, error) {
51		if err := validateName(name); err != nil {
52			return ExportResult{}, err
53		}
54		if strings.TrimSpace(output) == "" {
55			return ExportResult{}, errors.New("output is required")
56		}
57		if baseName != "" {
58			if err := validateName(baseName); err != nil {
59				return ExportResult{}, err
