63		var result ExportResult
64		err := s.withLock(false, func() error {
65			if _, err := os.Stat(s.indexPath()); err != nil {
66				if errors.Is(err, os.ErrNotExist) {
67					return fmt.Errorf("repository %q is not initialized; run init first", s.root)
68				}
69				return err
70			}
71	
72			target, err := s.loadSnapshot(name)
73			if err != nil {
74				return err
75			}
76			if err := validateSnapshot(target); err != nil {
77				return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
78			}
79	
80			var base *Snapshot
81			if baseName != "" {
82				b, err := s.loadSnapshot(baseName)
83				if err != nil {
84					return fmt.Errorf("base snapshot: %w", err)
85				}
86				if err := validateSnapshot(b); err != nil {
87					return fmt.Errorf("base snapshot %q is corrupted: %w", baseName, err)
88				}
89				base = &b
90			}
91	
92			targetDigests := snapshotDigestSet(target)
93			var baseDigests map[string]struct{}
