96			}
97	
98			// Verify ALL target-referenced objects, including ones omitted from
99			// an incremental package. A missing or corrupted object must not
100			// produce a successful package.
101			verified := map[string]struct{}{}
102			for _, entry := range target.Entries {
103				if _, ok := verified[entry.Digest]; ok {
104					continue
