127			if err := os.MkdirAll(filepath.Dir(output), 0o755); err != nil {
128				return err
129			}
130			tmp, err := os.CreateTemp(filepath.Dir(output), ".snapshot-package-*")
131			if err != nil {
132				return err
133			}
134			tmpName := tmp.Name()
135			defer os.Remove(tmpName)
