137			tw := tar.NewWriter(tmp)
138	
139			manifestData, err := json.MarshalIndent(manifest, "", "  ")
140			if err != nil {
141				return err
142			}
143			manifestData = append(manifestData, '\n')
144			if err := tw.WriteHeader(&tar.Header{
145				Name: "manifest.json",
146				Mode: 0o644,
147				Size: int64(len(manifestData)),
148			}); err != nil {
