160				if err := tw.WriteHeader(&tar.Header{
161					Name: "objects/" + digest,
162					Mode: 0o644,
163					Size: int64(len(data)),
164				}); err != nil {
165					return err
166				}
167				if _, err := tw.Write(data); err != nil {
168					return err
169				}
170			}
171	
172			if err := tw.Close(); err != nil {
173				return err
174			}
175			if err := tmp.Close(); err != nil {
176				return err
177			}
178			if err := os.Rename(tmpName, output); err != nil {
179				return err
180			}
