191	// ImportSnapshot reads a package and adds its snapshot to the repository. The
192	// current name mapping is never modified. A full package may be imported into
193	// an empty repository; an incremental package requires the target repository
194	// to already contain a base snapshot with identical metadata and intact
195	// referenced objects. Existing healthy objects with the same digest are reused;
196	// corrupted objects cause rejection. A snapshot with the same name and
197	// identical metadata is a no-op success; a same-name snapshot with different
198	// metadata is rejected.
199	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
200		if strings.TrimSpace(file) == "" {
201			return ImportResult{}, errors.New("file is required")
202		}
203	
204		var result ImportResult
205		err := s.withLock(true, func() error {
206			if err := s.initLocked(); err != nil {
207				return err
208			}
209	
210			manifest, objectFiles, err := readPackage(file, s)
211			if err != nil {
212				return fmt.Errorf("cannot import package: %w", err)
213			}
214			defer func() {
215				for _, path := range objectFiles {
216					os.Remove(path)
217				}
218			}()
219	
220			if manifest.Version != packageVersion {
221				return fmt.Errorf("cannot import package: unknown version %d", manifest.Version)
222			}
223	
224			target := manifest.Snapshot
225			if err := validateName(target.Name); err != nil {
226				return fmt.Errorf("cannot import package: invalid snapshot name: %w", err)
227			}
228			if err := validateSnapshot(target); err != nil {
229				return fmt.Errorf("cannot import package: snapshot is corrupted: %w", err)
230			}
231	
232			var base *Snapshot
233			if manifest.Base != nil {
234				b := manifest.Base
235				if err := validateName(b.Name); err != nil {
236					return fmt.Errorf("cannot import package: invalid base snapshot name: %w", err)
237				}
238				if err := validateSnapshot(*b); err != nil {
239					return fmt.Errorf("cannot import package: base snapshot is corrupted: %w", err)
240				}
241				base = b
242			}
243	
244			targetDigests := snapshotDigestSet(target)
245			var baseDigests map[string]struct{}
246			if base != nil {
247				baseDigests = snapshotDigestSet(*base)
248			}
249	
250			// Determine which digests the package is expected to carry.
251			expectedPackageDigests := map[string]struct{}{}
252			for digest := range targetDigests {
253				if base == nil {
254					expectedPackageDigests[digest] = struct{}{}
255				} else if _, inBase := baseDigests[digest]; !inBase {
256					expectedPackageDigests[digest] = struct{}{}
257				}
258			}
259	
260			// Every expected object must be present and intact; no unexpected
261			// objects may be carried.
262			for digest := range expectedPackageDigests {
263				if _, ok := objectFiles[digest]; !ok {
264					return fmt.Errorf("cannot import package: missing object %s", digest)
265				}
266			}
267			for digest := range objectFiles {
268				if _, ok := expectedPackageDigests[digest]; !ok {
269					return fmt.Errorf("cannot import package: unexpected object %s", digest)
270				}
271			}
272	
273			// Verify package objects against their recorded size and digest.
274			for digest, path := range objectFiles {
275				entry := findEntryByDigest(target, digest)
276				if err := verifyObjectFile(path, entry); err != nil {
277					return fmt.Errorf("cannot import package: object %s: %w", digest, err)
278				}
279			}
280	
281			// For incremental packages, the target repository must already have
282			// the exact base snapshot: same name, same entries. A same-name
283			// snapshot with different metadata, or merely sharing some digests,
284			// is not a substitute. The base's referenced objects must also be
285			// intact.
286			if base != nil {
287				existingBase, err := s.loadSnapshot(base.Name)
288				if err != nil {
289					return fmt.Errorf("cannot import package: %w", err)
290				}
291				if !snapshotsEqual(existingBase, *base) {
292					return fmt.Errorf("cannot import package: base snapshot %q metadata mismatch", base.Name)
293				}
294				for digest := range baseDigests {
295					entry := findEntryByDigest(*base, digest)
296					if err := s.verifyObject(entry); err != nil {
297						return fmt.Errorf("cannot import package: base object %s: %w", digest, err)
298					}
299				}
300			}
301	
302			// Add objects that are not already present. Existing objects are
303			// verified and reused; corrupted objects cause rejection.
304			added := 0
305			for digest := range expectedPackageDigests {
306				objectPath := s.objectPath(digest)
307				if _, err := os.Stat(objectPath); err == nil {
308					entry := findEntryByDigest(target, digest)
309					if err := s.verifyObject(entry); err != nil {
310						return fmt.Errorf("cannot import package: existing object %s is corrupted: %w", digest, err)
311					}
312					continue
313				} else if !errors.Is(err, os.ErrNotExist) {
314					return err
315				}
316				if err := os.Rename(objectFiles[digest], objectPath); err != nil {
317					return fmt.Errorf("cannot import package: failed to write object %s: %w", digest, err)
318				}
319				delete(objectFiles, digest)
320				added++
321			}
322	
323			// Publish the snapshot. A same-name snapshot with identical metadata
324			// is a no-op success; a same-name snapshot with different metadata is
325			// rejected.
326			existingSnap, err := s.loadSnapshot(target.Name)
327			if err == nil {
328				if snapshotsEqual(existingSnap, target) {
329					result = ImportResult{Name: target.Name, Entries: len(target.Entries), Added: added}
330					return nil
331				}
332				return fmt.Errorf("cannot import package: snapshot %q already exists with different metadata", target.Name)
333			} else if !errors.Is(err, os.ErrNotExist) {
334				return err
335			}
336	
337			if err := s.saveSnapshot(s.snapshotPath(target.Name), target); err != nil {
338				return fmt.Errorf("cannot import package: failed to write snapshot: %w", err)
339			}
340	
341			result = ImportResult{Name: target.Name, Entries: len(target.Entries), Added: added}
342			return nil
343		})
344		if err != nil {
345			return ImportResult{}, err
346		}
347		return result, nil
348	}
