350	// readPackage opens a snapshot package and returns its parsed manifest and a
351	// map of digest to temp file path for each carried object. The manifest is
352	// checked for duplicate keys before parsing. Only manifest.json and
353	// objects/<digest> entries are accepted; anything else is an error.
354	func readPackage(file string, s *Store) (manifest packageManifest, objectFiles map[string]string, err error) {
355		f, err := os.Open(file)
356		if err != nil {
357			return packageManifest{}, nil, err
358		}
359		defer f.Close()
360	
361		if err := os.MkdirAll(s.objectsDir(), 0o755); err != nil {
362			return packageManifest{}, nil, err
363		}
364	
365		objectFiles = map[string]string{}
366		defer func() {
367			if err != nil {
368				for _, path := range objectFiles {
369					os.Remove(path)
370				}
371			}
372		}()
373	
374		tr := tar.NewReader(f)
375		var manifestData []byte
376		manifestRead := false
377	
378		for {
379			hdr, err := tr.Next()
380			if err == io.EOF {
381				break
382			}
383			if err != nil {
384				return packageManifest{}, nil, err
385			}
386	
387			if hdr.Typeflag != tar.TypeReg {
388				return packageManifest{}, nil, fmt.Errorf("package contains non-regular file %q", hdr.Name)
389			}
390	
391			if hdr.Name == "manifest.json" {
392				if manifestRead {
393					return packageManifest{}, nil, errors.New("package contains multiple manifests")
394				}
395				data, err := io.ReadAll(tr)
396				if err != nil {
397					return packageManifest{}, nil, err
398				}
399				manifestData = data
400				manifestRead = true
401				continue
402			}
403	
404			if !strings.HasPrefix(hdr.Name, "objects/") {
405				return packageManifest{}, nil, fmt.Errorf("package contains unexpected file %q", hdr.Name)
406			}
407			digest := strings.TrimPrefix(hdr.Name, "objects/")
408			if digest == "" || strings.Contains(digest, "/") {
409				return packageManifest{}, nil, fmt.Errorf("package contains invalid object path %q", hdr.Name)
410			}
411			if !isDigest(digest) {
412				return packageManifest{}, nil, fmt.Errorf("package contains invalid object digest %q", digest)
413			}
414			if _, exists := objectFiles[digest]; exists {
415				return packageManifest{}, nil, fmt.Errorf("package contains duplicate object %q", digest)
416			}
417	
418			tmp, err := os.CreateTemp(s.objectsDir(), ".import-object-*")
419			if err != nil {
420				return packageManifest{}, nil, err
421			}
422			tmpName := tmp.Name()
423			n, copyErr := io.Copy(tmp, tr)
424			closeErr := tmp.Close()
425			if copyErr != nil {
426				os.Remove(tmpName)
427				return packageManifest{}, nil, copyErr
428			}
429			if closeErr != nil {
430				os.Remove(tmpName)
431				return packageManifest{}, nil, closeErr
432			}
433			if n != hdr.Size {
434				os.Remove(tmpName)
435				return packageManifest{}, nil, fmt.Errorf("package object %s size mismatch: header says %d, got %d", digest, hdr.Size, n)
436			}
437			objectFiles[digest] = tmpName
438		}
439	
440		if !manifestRead {
441			return packageManifest{}, nil, errors.New("package is missing manifest")
442		}
443	
444		if err := checkDuplicateKeys(manifestData); err != nil {
445			return packageManifest{}, nil, fmt.Errorf("package manifest is malformed: %w", err)
446		}
447		if err := json.Unmarshal(manifestData, &manifest); err != nil {
448			return packageManifest{}, nil, fmt.Errorf("package manifest is malformed: %w", err)
449		}
450		// Reject trailing data after the top-level value.
451		dec := json.NewDecoder(bytes.NewReader(manifestData))
452		var raw json.RawMessage
453		if err := dec.Decode(&raw); err != nil {
454			return packageManifest{}, nil, fmt.Errorf("package manifest is malformed: %w", err)
455		}
456		if err := dec.Decode(&raw); err != io.EOF {
457			return packageManifest{}, nil, errors.New("package manifest has trailing data")
458		}
459	
460		return manifest, objectFiles, nil
461	}
462	
463	// loadSnapshot reads a snapshot record from disk and verifies that its
464	// recorded name matches its location.
465	func (s *Store) loadSnapshot(name string) (Snapshot, error) {
466		data, err := os.ReadFile(s.snapshotPath(name))
467		if errors.Is(err, os.ErrNotExist) {
468			return Snapshot{}, fmt.Errorf("snapshot %q not found: %w", name, err)
469		}
470		if err != nil {
471			return Snapshot{}, err
472		}
473		var snap Snapshot
474		if err := json.Unmarshal(data, &snap); err != nil {
475			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
476		}
477		if snap.Name != name {
478			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: recorded name %q does not match its location", name, snap.Name)
479		}
480		return snap, nil
481	}
482	
483	// validateSnapshot checks a snapshot's entries the same way restore and GC do:
484	// the entries mapping must be present, each entry must be filed under its
485	// recorded name, and names, digests, and sizes must be legal.
486	func validateSnapshot(snap Snapshot) error {
487		if snap.Entries == nil {
488			return errors.New("missing entries mapping")
489		}
490		for key, entry := range snap.Entries {
491			if err := validateEntryRecord(key, entry); err != nil {
492				return err
493			}
494		}
495		return nil
496	}
497	
498	// snapshotDigestSet returns the set of content digests referenced by a
499	// snapshot's entries.
500	func snapshotDigestSet(snap Snapshot) map[string]struct{} {
501		digests := map[string]struct{}{}
502		for _, entry := range snap.Entries {
503			digests[entry.Digest] = struct{}{}
504		}
505		return digests
506	}
507	
508	// findEntryByDigest returns one entry with the given digest from a snapshot.
509	func findEntryByDigest(snap Snapshot, digest string) Entry {
510		for _, entry := range snap.Entries {
511			if entry.Digest == digest {
512				return entry
513			}
514		}
515		return Entry{}
516	}
517	
518	// snapshotsEqual reports whether two snapshots have the same name and identical
519	// entry metadata.
520	func snapshotsEqual(a, b Snapshot) bool {
521		if a.Name != b.Name {
522			return false
523		}
524		if len(a.Entries) != len(b.Entries) {
525			return false
526		}
527		for key, entryA := range a.Entries {
528			entryB, ok := b.Entries[key]
529			if !ok {
530				return false
531			}
532			if !entriesEqual(entryA, entryB) {
533				return false
534			}
535		}
536		return true
537	}
538	
539	// entriesEqual reports whether two entries have identical metadata. The
540	// creation timestamp is not part of the comparison: it records when an
541	// artifact was uploaded and differs across repositories, while the entry's
542	// identity is its name, digest, and size.
543	func entriesEqual(a, b Entry) bool {
544		return a.Name == b.Name && a.Digest == b.Digest && a.Size == b.Size
545	}
546	
547	// verifyObjectFile checks that the file at path has the size and SHA-256
548	// recorded in entry.
549	func verifyObjectFile(path string, entry Entry) error {
550		f, err := os.Open(path)
551		if err != nil {
552			return err
553		}
554		defer f.Close()
555		hash := sha256.New()
556		size, err := io.Copy(hash, f)
557		if err != nil {
558			return err
559		}
560		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
561			return errors.New("content mismatch")
562		}
563		return nil
564	}
565	
566	// checkDuplicateKeys reports whether a JSON document contains duplicate keys
567	// in any object.
568	func checkDuplicateKeys(data []byte) error {
569		dec := json.NewDecoder(bytes.NewReader(data))
570		return checkDupKeys(dec)
571	}
572	
573	func checkDupKeys(dec *json.Decoder) error {
574		tok, err := dec.Token()
575		if err != nil {
576			return err
577		}
578		switch d := tok.(type) {
579		case json.Delim:
580			switch d {
581			case '{':
582				seen := map[string]bool{}
583				for dec.More() {
584					keyTok, err := dec.Token()
585					if err != nil {
586						return err
587					}
588					key, ok := keyTok.(string)
589					if !ok {
590						return errors.New("expected string key in JSON object")
591					}
592					if seen[key] {
593						return fmt.Errorf("duplicate key %q", key)
594					}
595					seen[key] = true
596					if err := checkDupKeys(dec); err != nil {
597						return err
598					}
599				}
600				if _, err := dec.Token(); err != nil {
601					return err
602				}
603			case '[':
604				for dec.More() {
605					if err := checkDupKeys(dec); err != nil {
606						return err
607					}
608				}
609				if _, err := dec.Token(); err != nil {
610					return err
611				}
612			}
613		}
614		return nil
615	}
616	
617	// sortedKeys returns the keys of a string set in sorted order.
618	func sortedKeys(set map[string]struct{}) []string {
