1	package main
2	
3	import (
4		"flag"
5		"fmt"
6		"os"
7	
8		"github.com/Hulalalalalalalalalalala/artifact-vault/internal/vault"
9	)
10	
11	func main() {
12		if err := run(os.Args[1:]); err != nil {
13			fmt.Fprintln(os.Stderr, "error:", err)
14			os.Exit(1)
15		}
16	}
17	
18	func run(args []string) error {
19		if len(args) == 0 {
20			return fmt.Errorf("usage: artifact-vault <init|put|get|list|verify|snapshot|gc>")
21		}
22		command := args[0]
23		if command == "snapshot" {
24			return runSnapshot(args[1:])
25		}
26		flags := flag.NewFlagSet(command, flag.ContinueOnError)
27		root := flags.String("root", "./vault", "vault directory")
28		name := flags.String("name", "", "logical artifact name")
29		file := flags.String("file", "", "input file")
30		output := flags.String("output", "", "output file")
31		dryRun := flags.Bool("dry-run", false, "preview garbage collection without deleting anything")
32		if err := flags.Parse(args[1:]); err != nil {
33			return err
34		}
35		store := vault.New(*root)
36		switch command {
37		case "init":
38			return store.Init()
39		case "put":
40			entry, err := store.Put(*name, *file)
41			if err == nil {
42				fmt.Printf("stored %s sha256=%s size=%d\n", entry.Name, entry.Digest, entry.Size)
43			}
44			return err
45		case "get":
46			return store.Get(*name, *output)
47		case "list":
48			entries, err := store.List()
49			if err != nil {
50				return err
51			}
52			for _, entry := range entries {
53				fmt.Printf("%s\t%s\t%d\n", entry.Name, entry.Digest, entry.Size)
54			}
55			return nil
56		case "verify":
57			count, err := store.Verify()
58			if err == nil {
59				fmt.Printf("verified %d artifacts\n", count)
60			}
61			return err
62		case "gc":
63			report, err := store.GC(*dryRun)
64			if err != nil {
65				return err
66			}
67			if *dryRun {
68				var bytes int64
69				for _, candidate := range report.Candidates {
70					fmt.Printf("%s\t%d\n", candidate.Digest, candidate.Size)
71					bytes += candidate.Size
72				}
73				fmt.Printf("total %d objects, %d bytes\n", len(report.Candidates), bytes)
74				return nil
75			}
76			fmt.Printf("deleted %d objects, %d bytes\n", report.Deleted, report.Bytes)
77			return nil
78		default:
79			return fmt.Errorf("unknown command %q", command)
80		}
81	}
82	
83	func runSnapshot(args []string) error {
84		if len(args) == 0 {
85			return fmt.Errorf("usage: artifact-vault snapshot <create|list|restore|export|import> --root <dir> [--name <snapshot>] [--output <file>] [--base <snapshot>] [--file <package>]")
86		}
87		sub := args[0]
88		flags := flag.NewFlagSet("snapshot "+sub, flag.ContinueOnError)
89		root := flags.String("root", "./vault", "vault directory")
90		name := flags.String("name", "", "snapshot name")
91		output := flags.String("output", "", "output package file")
92		base := flags.String("base", "", "base snapshot name for incremental export")
93		file := flags.String("file", "", "package file to import")
94		if err := flags.Parse(args[1:]); err != nil {
95			return err
96		}
97		store := vault.New(*root)
98		switch sub {
99		case "create":
100			snap, err := store.CreateSnapshot(*name)
101			if err == nil {
102				fmt.Printf("snapshot %s created with %d entries\n", snap.Name, len(snap.Entries))
103			}
104			return err
105		case "list":
106			infos, err := store.ListSnapshots()
107			if err != nil {
108				return err
109			}
110			for _, info := range infos {
111				fmt.Printf("%s\t%d\n", info.Name, info.Count)
112			}
113			return nil
114		case "restore":
115			if err := store.RestoreSnapshot(*name); err != nil {
116				return err
117			}
118			fmt.Printf("restored snapshot %s\n", *name)
119			return nil
120		case "export":
